//! Lillith's icon set (`branding/icons.toml`) and applying the user's pick.
//!
//! The registry is compiled in from `branding/icons.toml` (generated by
//! `branding/make-icons.py`). The files live in an *icons root* with one
//! folder per icon:
//!
//! ```text
//! <root>/<id>/lillith-<N>.png   N = 16 24 32 48 64 128 256 (hicolor, thumbnails)
//! <root>/<id>/<id>.ico          Windows (the installer also puts <root>/<id>.ico)
//! ```
//!
//! [`icons_dir`] finds the root: `$LILLITH_ICONS_DIR`, `icons/` next to the
//! executable (Windows install, portable zip), `$XDG_DATA_HOME/lillith/icons`
//! (`linux/install.sh`), `$XDG_DATA_DIRS/*/lillith/icons` (PKGBUILD), then a
//! source checkout's `branding/icons`.
//!
//! The choice is the top-level `icon = "<id>"` of config.toml
//! ([`crate::config::Config::icon`]); [`apply`] makes the desktop show it:
//!
//! - Linux: copies the icon over `~/.local/share/icons/hicolor/<N>x<N>/apps/lillith.png`
//!   (the theme icon every `Icon=lillith` entry uses), touches the menu entry
//!   and the desktop shortcut and refreshes the icon caches
//!   (`gtk-update-icon-cache`, `kbuildsycoca6`) when those tools exist.
//! - Windows: the icon embedded in the .exe stays the default; the Start-menu,
//!   Desktop and Startup shortcuts that start `lillith.exe` /
//!   `lillith-settings.exe` get `IconLocation` =
//!   `<root>\<id>.ico` (PowerShell + WScript.Shell), then the shell icon
//!   cache is refreshed (`SHChangeNotify(SHCNE_ASSOCCHANGED)`).
//! - Android does it in Java (activity-alias per icon, `SetupActivity`).

use serde::Deserialize;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

/// The icon used when config.toml has none (or an unknown id).
pub const DEFAULT_ICON: &str = "phantomcore-red";

const ICONS_TOML: &str = include_str!("../../../branding/icons.toml");

/// One icon of the set.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct IconInfo {
    /// Stable id (config value, folder name), e.g. `phantomcore-red`.
    pub id: String,
    /// Display name, e.g. "Phantomcore Red".
    pub name: String,
    /// Paths relative to `branding/` (documentation; see [`png_path`]).
    pub master: String,
    pub png: String,
    pub ico: String,
    /// Android mipmap of the icon's activity-alias.
    pub android: String,
}

#[derive(Debug, Deserialize)]
struct Registry {
    default: String,
    sizes: Vec<u32>,
    icon: Vec<IconInfo>,
}

fn registry() -> &'static Registry {
    static R: OnceLock<Registry> = OnceLock::new();
    R.get_or_init(|| toml::from_str(ICONS_TOML).expect("branding/icons.toml is valid"))
}

/// Every icon, in picker order.
pub fn all() -> &'static [IconInfo] {
    &registry().icon
}

/// PNG sizes each icon has.
pub fn sizes() -> &'static [u32] {
    &registry().sizes
}

/// The registry's default id (same as [`DEFAULT_ICON`]).
pub fn default_id() -> &'static str {
    &registry().default
}

pub fn find(id: &str) -> Option<&'static IconInfo> {
    all().iter().find(|i| i.id == id.trim())
}

/// `id` if it is in the set, else the default.
pub fn resolve(id: Option<&str>) -> &'static IconInfo {
    id.and_then(find)
        .or_else(|| find(default_id()))
        .unwrap_or(&all()[0])
}

/// `<root>/<id>/lillith-<size>.png`.
pub fn png_path(root: &Path, id: &str, size: u32) -> PathBuf {
    root.join(id).join(format!("lillith-{size}.png"))
}

/// The smallest PNG of `id` that is at least `min` px (else the largest).
pub fn thumbnail(root: &Path, id: &str, min: u32) -> Option<PathBuf> {
    let mut s: Vec<u32> = sizes().to_vec();
    s.sort_unstable();
    s.iter()
        .filter(|&&n| n >= min)
        .chain(s.iter().rev())
        .map(|&n| png_path(root, id, n))
        .find(|p| p.is_file())
}

/// The `.ico` of `id`: `<root>/<id>.ico` (Windows install layout), else
/// `<root>/<id>/<id>.ico`.
pub fn ico_path(root: &Path, id: &str) -> PathBuf {
    let flat = root.join(format!("{id}.ico"));
    if flat.is_file() {
        flat
    } else {
        root.join(id).join(format!("{id}.ico"))
    }
}

fn is_icons_root(p: &Path) -> bool {
    let d = default_id();
    p.join(d).is_dir() || p.join(format!("{d}.ico")).is_file()
}

/// Where the icon files are (see the module docs for the order).
pub fn icons_dir() -> Option<PathBuf> {
    icons_dir_candidates()
        .into_iter()
        .find(|p| is_icons_root(p))
}

fn icons_dir_candidates() -> Vec<PathBuf> {
    let mut c = Vec::new();
    if let Some(p) = std::env::var_os("LILLITH_ICONS_DIR").filter(|v| !v.is_empty()) {
        c.push(PathBuf::from(p));
    }
    let exe_dir = std::env::current_exe()
        .ok()
        .and_then(|e| e.parent().map(Path::to_path_buf));
    if let Some(d) = &exe_dir {
        c.push(d.join("icons"));
    }
    if let Some(d) = data_home() {
        c.push(d.join("lillith").join("icons"));
    }
    #[cfg(unix)]
    {
        let dirs = std::env::var("XDG_DATA_DIRS")
            .ok()
            .filter(|v| !v.is_empty())
            .unwrap_or_else(|| "/usr/local/share:/usr/share".into());
        for d in dirs.split(':').filter(|d| d.starts_with('/')) {
            c.push(Path::new(d).join("lillith").join("icons"));
        }
    }
    c.push(PathBuf::from("branding").join("icons"));
    if let Some(d) = &exe_dir {
        // target/{debug,release}/lillith in a checkout
        c.push(d.join("../../branding/icons"));
    }
    c
}

/// `$XDG_DATA_HOME`, else `~/.local/share` (Windows: `%LOCALAPPDATA%`).
pub fn data_home() -> Option<PathBuf> {
    let x = std::env::var_os("XDG_DATA_HOME")
        .map(PathBuf::from)
        .filter(|p| p.is_absolute());
    #[cfg(windows)]
    let x = x.or_else(|| std::env::var_os("LOCALAPPDATA").map(PathBuf::from));
    x.or_else(|| std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".local/share")))
}

/// What [`apply`] did.
#[derive(Debug, Default, Clone, PartialEq)]
pub struct Applied {
    pub id: String,
    /// Files written (theme icons) or shortcuts changed.
    pub changed: Vec<PathBuf>,
    /// Human-readable notes (skipped steps, tools run).
    pub notes: Vec<String>,
}

/// Makes the desktop show icon `id` (see the module docs). `root` = the
/// icons root ([`icons_dir`]).
pub fn apply(root: &Path, id: &str) -> Result<Applied, String> {
    let info = find(id).ok_or_else(|| format!("unknown icon {id:?}"))?;
    #[cfg(windows)]
    {
        // Rewriting the Windows shortcuts runs PowerShell: that needs Ko's
        // Yes on a Soul Contract card first (Settings → Icon shows it, then
        // calls [`apply_windows_shortcuts`]). Nothing runs here.
        let ico = ico_path(root, &info.id);
        if !ico.is_file() {
            return Err(format!("missing {}", ico.display()));
        }
        Ok(Applied {
            id: info.id.clone(),
            changed: Vec::new(),
            notes: vec![WINDOWS_NEEDS_CARD.to_string()],
        })
    }
    #[cfg(all(unix, not(target_os = "android")))]
    {
        let data = data_home().ok_or("no $HOME / $XDG_DATA_HOME")?;
        let mut a = apply_linux(root, &info.id, &data, desktop_dir().as_deref())?;
        refresh_linux(&data, &mut a);
        Ok(a)
    }
    #[cfg(not(any(windows, all(unix, not(target_os = "android")))))]
    {
        let _ = root;
        Err(format!("applying icon {} is not supported here", info.id))
    }
}

/// The user's desktop folder: `$XDG_DESKTOP_DIR`, `xdg-user-dir DESKTOP`,
/// else `~/Desktop`.
#[cfg(all(unix, not(target_os = "android")))]
pub fn desktop_dir() -> Option<PathBuf> {
    if let Some(d) = std::env::var_os("XDG_DESKTOP_DIR").filter(|v| !v.is_empty()) {
        return Some(PathBuf::from(d));
    }
    let mut c = std::process::Command::new("xdg-user-dir");
    c.arg("DESKTOP").stderr(std::process::Stdio::null());
    crate::launch_audit::record_command_once("icon_desktop_dir", &c);
    if let Ok(o) = c.output() {
        let s = String::from_utf8_lossy(&o.stdout).trim().to_string();
        if o.status.success() && s.starts_with('/') {
            return Some(PathBuf::from(s));
        }
    }
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join("Desktop"))
}

/// The file part of the Linux apply (no external tools): copies the icon's
/// PNGs over `<data>/icons/hicolor/<N>x<N>/apps/lillith.png`, removes a
/// stale 512 px one from an older install, and touches the menu entry and
/// the desktop shortcut (`<desktop>/lillith.desktop`) so file managers and
/// docks reload them.
#[cfg(unix)]
pub fn apply_linux(
    root: &Path,
    id: &str,
    data: &Path,
    desktop: Option<&Path>,
) -> Result<Applied, String> {
    let mut a = Applied {
        id: id.to_string(),
        ..Default::default()
    };
    let hicolor = data.join("icons").join("hicolor");
    for &n in sizes() {
        let src = png_path(root, id, n);
        if !src.is_file() {
            a.notes.push(format!("missing {}", src.display()));
            continue;
        }
        let dir = hicolor.join(format!("{n}x{n}")).join("apps");
        let dst = dir.join("lillith.png");
        let tmp = dir.join(".lillith.png.tmp");
        std::fs::create_dir_all(&dir)
            .and_then(|()| std::fs::copy(&src, &tmp))
            .and_then(|_| std::fs::rename(&tmp, &dst))
            .map_err(|e| format!("{}: {e}", dst.display()))?;
        a.changed.push(dst);
    }
    if a.changed.is_empty() {
        return Err(format!(
            "no PNGs for icon {id} in {} (reinstall Lillith?)",
            root.display()
        ));
    }
    // An older install shipped a 512 px icon; it would win at large sizes.
    let stale = hicolor.join("512x512/apps/lillith.png");
    if !sizes().contains(&512) && stale.is_file() && std::fs::remove_file(&stale).is_ok() {
        a.notes.push(format!("removed {}", stale.display()));
    }
    let now = std::time::SystemTime::now();
    let mut touch = |p: PathBuf| {
        if let Ok(f) = std::fs::File::options().append(true).open(&p) {
            if f.set_modified(now).is_ok() {
                a.changed.push(p);
            }
        }
    };
    touch(data.join("applications").join("lillith.desktop"));
    if let Some(d) = desktop {
        touch(d.join("lillith.desktop"));
    }
    if let Ok(f) = std::fs::File::open(&hicolor) {
        let _ = f.set_modified(now);
    }
    Ok(a)
}

#[cfg(all(unix, not(target_os = "android")))]
fn refresh_linux(data: &Path, a: &mut Applied) {
    let hicolor = data.join("icons").join("hicolor");
    let mut run = |prog: &str, args: &[&std::ffi::OsStr]| {
        if find_program(prog).is_none() {
            return;
        }
        let mut c = std::process::Command::new(prog);
        c.args(args)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        crate::launch_audit::record_command("icon_refresh", &c);
        let ok = c.status().is_ok_and(|s| s.success());
        a.notes
            .push(format!("{prog}: {}", if ok { "ok" } else { "failed" }));
    };
    run(
        "gtk-update-icon-cache",
        &[
            "-q".as_ref(),
            "-t".as_ref(),
            "-f".as_ref(),
            hicolor.as_os_str(),
        ],
    );
    if find_program("kbuildsycoca6").is_some() {
        run("kbuildsycoca6", &[]);
    } else {
        run("kbuildsycoca5", &[]);
    }
}

/// `prog` on `$PATH`.
pub fn find_program(prog: &str) -> Option<PathBuf> {
    let exe = format!("{prog}{}", std::env::consts::EXE_SUFFIX);
    std::env::split_paths(&std::env::var_os("PATH")?)
        .map(|d| d.join(&exe))
        .find(|p| p.is_file())
}

/// PowerShell that re-points every Start-menu / Desktop / Startup shortcut
/// whose target is `lillith.exe` or `lillith-settings.exe` at
/// `$env:LILLITH_ICON`, then refreshes the shell
/// icon cache. Prints the number of shortcuts changed.
pub const WINDOWS_SHORTCUT_PS: &str = r#"
$ErrorActionPreference = 'SilentlyContinue'
$ws = New-Object -ComObject WScript.Shell
$n = 0
foreach ($k in 'Programs','CommonPrograms','Desktop','CommonDesktopDirectory','Startup') {
  $d = [Environment]::GetFolderPath($k)
  if (-not $d -or -not (Test-Path -LiteralPath $d)) { continue }
  Get-ChildItem -LiteralPath $d -Filter *.lnk -Recurse -Depth 1 | ForEach-Object {
    $s = $ws.CreateShortcut($_.FullName)
    $exe = if ($s.TargetPath) { [IO.Path]::GetFileName($s.TargetPath).ToLowerInvariant() } else { '' }
    if ($exe -eq 'lillith.exe' -or $exe -eq 'lillith-settings.exe') {
      $s.IconLocation = $env:LILLITH_ICON + ',0'
      $s.Save()
      $n++
    }
  }
}
Add-Type -Namespace Lillith -Name Shell -MemberDefinition '[System.Runtime.InteropServices.DllImport("shell32.dll")] public static extern void SHChangeNotify(int e, uint f, System.IntPtr a, System.IntPtr b);'
[Lillith.Shell]::SHChangeNotify(0x08000000, 0x1000, [System.IntPtr]::Zero, [System.IntPtr]::Zero)
Write-Output $n
"#;

/// What [`apply`] notes on Windows instead of running PowerShell.
pub const WINDOWS_NEEDS_CARD: &str =
    "the Windows shortcuts change only after your Yes on the Soul Contract card (Settings → Icon)";

/// Base64 (standard alphabet, padded).
pub fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for ch in bytes.chunks(3) {
        let b = [ch[0], *ch.get(1).unwrap_or(&0), *ch.get(2).unwrap_or(&0)];
        let n = (u32::from(b[0]) << 16) | (u32::from(b[1]) << 8) | u32::from(b[2]);
        for i in 0..4 {
            if i <= ch.len() {
                out.push(T[((n >> (18 - 6 * i)) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

/// PowerShell's `-EncodedCommand` form of `script` (base64 of UTF-16LE).
/// Execution policy only governs script *files*; an encoded command is
/// not one, so no `-ExecutionPolicy Bypass` is needed.
pub fn powershell_encoded(script: &str) -> String {
    let bytes: Vec<u8> = script.encode_utf16().flat_map(u16::to_le_bytes).collect();
    base64(&bytes)
}

/// The exact command the Windows shortcut rewrite runs (its icon path
/// goes in `$env:LILLITH_ICON`).
pub fn windows_shortcut_argv() -> Vec<String> {
    [
        "powershell.exe",
        "-NoProfile",
        "-NonInteractive",
        "-EncodedCommand",
    ]
    .iter()
    .map(|s| s.to_string())
    .chain(std::iter::once(powershell_encoded(WINDOWS_SHORTCUT_PS)))
    .collect()
}

/// The Soul Contract card's detail for the shortcut rewrite: the command
/// one argument per line, the environment it gets and the decoded script.
pub fn windows_shortcut_detail(ico: &Path) -> String {
    let argv = windows_shortcut_argv();
    let mut s = format!("$ {}", argv[0]);
    for a in &argv[1..argv.len() - 1] {
        s.push_str(&format!("\n    {a}"));
    }
    s.push_str("\n    <the script below, UTF-16LE base64>");
    s.push_str(&format!("\nenv LILLITH_ICON={}\n\nScript:", ico.display()));
    for l in WINDOWS_SHORTCUT_PS.trim().lines() {
        s.push_str("\n  ");
        s.push_str(l);
    }
    s
}

/// Rewrites the Windows shortcuts' icon (see [`WINDOWS_SHORTCUT_PS`]).
/// Call only after Ko's Yes on the card; writes the launch's audit line
/// with that card's id. Not Windows: an error, nothing runs.
pub fn apply_windows_shortcuts(root: &Path, id: &str, card: &str) -> Result<Applied, String> {
    let ico = ico_path(root, id);
    if !ico.is_file() {
        return Err(format!("missing {}", ico.display()));
    }
    let argv = windows_shortcut_argv();
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        if let Some(log) = crate::config::audit_log_path() {
            crate::launch_audit::record_to(
                &log,
                crate::launch_audit::LAUNCH_TAG,
                ICON_CARD_KIND,
                &argv,
                Some(card),
            );
        }
        let out = std::process::Command::new(&argv[0])
            .args(&argv[1..])
            .env("LILLITH_ICON", &ico)
            .stdin(std::process::Stdio::null())
            .creation_flags(CREATE_NO_WINDOW)
            .output()
            .map_err(|e| format!("powershell: {e}"))?;
        let n = String::from_utf8_lossy(&out.stdout).trim().to_string();
        Ok(Applied {
            id: id.to_string(),
            changed: vec![ico.clone()],
            notes: vec![format!("{n} shortcut(s) now use {}", ico.display())],
        })
    }
    #[cfg(not(windows))]
    {
        let _ = (argv, card);
        Err("Windows shortcuts exist only on Windows".into())
    }
}

/// The `kind` column of the shortcut card's audit lines.
pub const ICON_CARD_KIND: &str = "icon_shortcuts";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shortcut_command_is_encoded_without_an_execution_policy_bypass() {
        assert_eq!(base64(b""), "");
        assert_eq!(base64(b"f"), "Zg==");
        assert_eq!(base64(b"fo"), "Zm8=");
        assert_eq!(base64(b"foo"), "Zm9v");
        assert_eq!(base64(b"foobar"), "Zm9vYmFy");
        // PowerShell docs example: 'dir "c:\program files" ' encodes to this.
        assert_eq!(
            powershell_encoded("dir \"c:\\program files\" "),
            "ZABpAHIAIAAiAGMAOgBcAHAAcgBvAGcAcgBhAG0AIABmAGkAbABlAHMAIgAgAA=="
        );
        let argv = windows_shortcut_argv();
        assert!(!argv
            .iter()
            .any(|a| a.eq_ignore_ascii_case("-ExecutionPolicy")));
        assert!(!argv.iter().any(|a| a.eq_ignore_ascii_case("Bypass")));
        assert_eq!(argv[3], "-EncodedCommand");
        assert_eq!(argv.len(), 5);
        let d = windows_shortcut_detail(Path::new("C:/x/i.ico"));
        assert!(d.starts_with(
            "$ powershell.exe\n    -NoProfile\n    -NonInteractive\n    -EncodedCommand\n"
        ));
        assert!(d.contains("env LILLITH_ICON=C:/x/i.ico"));
        assert!(d.contains("$s.IconLocation = $env:LILLITH_ICON"));
        #[cfg(not(windows))]
        assert!(apply_windows_shortcuts(&repo_icons(), DEFAULT_ICON, "c").is_err());
    }

    fn repo_icons() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../branding/icons")
    }

    #[test]
    fn registry_has_the_set_and_the_default() {
        let ids: Vec<&str> = all().iter().map(|i| i.id.as_str()).collect();
        assert_eq!(ids.len(), 15);
        assert_eq!(default_id(), DEFAULT_ICON);
        assert_eq!(find(DEFAULT_ICON).unwrap().name, "Phantomcore Red");
        assert_eq!(find("classic").unwrap().name, "Classic");
        let mut dedup = ids.clone();
        dedup.sort_unstable();
        dedup.dedup();
        assert_eq!(dedup.len(), ids.len(), "duplicate ids");
        assert_eq!(resolve(Some("nope")).id, DEFAULT_ICON);
        assert_eq!(resolve(None).id, DEFAULT_ICON);
        assert_eq!(resolve(Some(" glitch ")).id, "glitch");
    }

    #[test]
    fn every_id_resolves_to_real_files() {
        let root = repo_icons();
        assert!(is_icons_root(&root));
        let branding = root.parent().unwrap();
        for i in all() {
            assert!(
                i.id.chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                "{}",
                i.id
            );
            assert!(branding.join(&i.master).is_file(), "{}", i.master);
            assert!(branding.join(&i.ico).is_file(), "{}", i.ico);
            assert_eq!(ico_path(&root, &i.id), branding.join(&i.ico));
            for &n in sizes() {
                let p = png_path(&root, &i.id, n);
                assert!(p.is_file(), "{}", p.display());
                assert_eq!(
                    p,
                    branding.join(i.png.replace("{size}", &n.to_string())),
                    "icons.toml png pattern"
                );
            }
            assert_eq!(
                i.android,
                format!("@mipmap/ic_icon_{}", i.id.replace('-', "_"))
            );
            let res = branding.join("../android/app/res");
            let m = i.android.trim_start_matches("@mipmap/");
            assert!(res.join(format!("mipmap-anydpi-v26/{m}.xml")).is_file());
            assert!(res.join(format!("mipmap-xxxhdpi/{m}_fg.png")).is_file());
        }
        let t = thumbnail(&root, DEFAULT_ICON, 100).unwrap();
        assert!(t.ends_with("phantomcore-red/lillith-128.png"));
    }

    #[cfg(unix)]
    #[test]
    fn apply_linux_rewrites_the_theme_icon() {
        let tmp = std::env::temp_dir().join(format!("lillith-icons-{}", std::process::id()));
        let data = tmp.join("share");
        let desk = tmp.join("Desktop");
        std::fs::create_dir_all(data.join("applications")).unwrap();
        std::fs::create_dir_all(data.join("icons/hicolor/512x512/apps")).unwrap();
        std::fs::create_dir_all(&desk).unwrap();
        std::fs::write(data.join("applications/lillith.desktop"), "x").unwrap();
        std::fs::write(desk.join("lillith.desktop"), "x").unwrap();
        std::fs::write(data.join("icons/hicolor/512x512/apps/lillith.png"), "old").unwrap();
        let root = repo_icons();
        let a = apply_linux(&root, "glitch", &data, Some(&desk)).unwrap();
        for &n in sizes() {
            let got = std::fs::read(data.join(format!("icons/hicolor/{n}x{n}/apps/lillith.png")));
            assert_eq!(
                got.unwrap(),
                std::fs::read(png_path(&root, "glitch", n)).unwrap()
            );
        }
        assert!(!data.join("icons/hicolor/512x512/apps/lillith.png").exists());
        assert!(a.changed.contains(&desk.join("lillith.desktop")));
        assert!(a
            .changed
            .contains(&data.join("applications/lillith.desktop")));
        // switching again overwrites
        apply_linux(&root, "classic", &data, None).unwrap();
        assert_eq!(
            std::fs::read(data.join("icons/hicolor/32x32/apps/lillith.png")).unwrap(),
            std::fs::read(png_path(&root, "classic", 32)).unwrap()
        );
        assert!(apply_linux(&tmp, "glitch", &data, None).is_err());
        std::fs::remove_dir_all(&tmp).unwrap();
    }
}
